+/// Every edge of every closed contour is reached by its own cut's kerf,
+/// outside the tip zone of its inside corners: `spans[pos]` is the cut
+/// of `cs[order[pos]]`.
+pub(super) fn cover_law(
+    path: &Toolpath,
+    spans: &[TorchSpan],
+    cs: &[Contour],
+    order: &[usize],
+    kerf: f64,
